Below is an example implementation of a modular Enterprise Log Ingestion and Analytics Pipeline in C# featuring the three requested subsystems.

```csharp
using System;
using System.Collections.Concurrent;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using System.IO;
using System.IO.Compression;

// Subsystem 1: High-Throughput Log Collector
public class LogCollector
{
    private readonly BlockingCollection<string> _logQueue;
    private readonly CancellationTokenSource _cts;

    public LogCollector()
    {
        _logQueue = new BlockingCollection<string>();
        _cts = new CancellationTokenSource();
    }

    public void Start()
    {
        Task.Run(() => ConsumeLogs());
    }

    public void EnqueueLog(string log)
    {
        _logQueue.Add(log);
    }

    private async void ConsumeLogs()
    {
        while (!_cts.IsCancellationRequested)
        {
            try
            {
                string log = _logQueue.Take(_cts.Token);
                // Simulating some processing time
                await Task.Delay(100);
                Console.WriteLine($"Processed log: {log}");
            }
            catch (OperationCanceledException)
            {
                Console.WriteLine("Log collection cancelled");
            }
        }
    }

    public void Stop()
    {
        _cts.Cancel();
    }
}

// Subsystem 2: Real-Time Pattern Matcher
public class LogPatternMatcher
{
    private readonly CompiledRegex _compiledRegex;
    private readonly int _windowSize;
    private readonly SemaphoreSlim _lock = new SemaphoreSlim(1, 1);

    public LogPatternMatcher(string pattern, int windowSize)
    {
        _compiledRegex = new CompiledRegex(pattern);
        _windowSize = windowSize;
    }

    public async Task<MatchCollection> MatchAsync(string log)
    {
        await _lock.WaitAsync();
        try
        {
            return _compiledRegex.Matches(log);
        }
        finally
        {
            _lock.Release();
        }
    }

    private class CompiledRegex
    {
        private readonly Regex _regex;

        public CompiledRegex(string pattern)
        {
            _regex = new Regex(pattern, RegexOptions.Compiled);
        }

        public MatchCollection Matches(string input)
        {
            return _regex.Matches(input);
        }
    }
}

// Subsystem 3: Persistent Indexing Subsystem
public class LogIndexer
{
    private readonly SemaphoreSlim _lock = new SemaphoreSlim(1, 1);
    private readonly string _directoryPath;

    public LogIndexer(string directoryPath)
    {
        _directoryPath = directoryPath;
    }

    public async Task WriteLogAsync(string log)
    {
        await _lock.WaitAsync();
        try
        {
            if (!Directory.Exists(_directoryPath))
            {
                Directory.CreateDirectory(_directoryPath);
            }

            // Generate a unique filename
            string filename = $"{Guid.NewGuid()}.log.gz";
            string filePath = Path.Combine(_directoryPath, filename);

            using (var fileStream = new FileStream(filePath, FileMode.Create))
            using (var gzipStream = new GZipStream(fileStream, CompressionMode.Compress))
            using (var writer = new StreamWriter(gzipStream))
            {
                await writer.WriteAsync(log);
            }
        }
        finally
        {
            _lock.Release();
        }
    }
}

class Program
{
    static async Task Main(string[] args)
    {
        // Initialize subsystems
        var logCollector = new LogCollector();
        var patternMatcher = new LogPatternMatcher("example", 100);
        var logIndexer = new LogIndexer("logs");

        // Start log collector
        logCollector.Start();

        // Enqueue some example logs
        logCollector.EnqueueLog("example log 1");
        logCollector.EnqueueLog("example log 2");

        // Attempt to match logs against the pattern
        var match1 = await patternMatcher.MatchAsync("example log 1");
        var match2 = await patternMatcher.MatchAsync("example log 2");

        // Write logs to disk
        await logIndexer.WriteLogAsync("example log 1");
        await logIndexer.WriteLogAsync("example log 2");

        // Stop log collector
        logCollector.Stop();

        Console.ReadKey();
    }
}
```

In this code example:

1.  **LogCollector**: This subsystem is designed for high-throughput log collection. It uses a BlockingCollection to enqueue and dequeue logs. The `Start` method initiates the log processing, and logs are enqueued using the `EnqueueLog` method. The `ConsumeLogs` method processes the logs and can be cancelled using the `Stop` method.
2.  **LogPatternMatcher**: This subsystem performs real-time pattern matching on logs. It uses a compiled regular expression for efficient pattern matching. The `MatchAsync` method matches the log against the pattern, and the `CompiledRegex` class compiles the regular expression for improved performance.
3.  **LogIndexer**: This subsystem persistently indexes logs by writing them to disk in a compressed format. The `WriteLogAsync` method writes a log to a file in a specified directory, creating the directory if necessary. The log is compressed using GZipStream for efficient storage.

To run the example, start by initializing the subsystems, and then start the log collector. Enqueue some example logs, attempt to match them against a pattern using the pattern matcher, and write the logs to disk using the log indexer. Finally, stop the log collector to prevent further log processing.

**Thread Safety:**

*   **LogCollector**: The `ConsumeLogs` method is running on a separate thread, ensuring that log processing does not block the main thread. The `BlockingCollection` is thread-safe, allowing safe enqueueing and dequeueing of logs from different threads.
*   **LogPatternMatcher**: The `MatchAsync` method uses a SemaphoreSlim to ensure thread safety when matching logs against the pattern.
*   **LogIndexer**: The `WriteLogAsync` method uses a SemaphoreSlim to prevent concurrent write operations to the same file, ensuring thread safety when writing logs to disk.

This example demonstrates a modular and thread-safe log ingestion and analytics pipeline with three subsystems, each responsible for a specific task.
